const initialState = () => ({ user:null, role:'teacher', name:'', view:'dashboard', students:[], classes:[], records:[], competencies:[], assessments:[], observations:[], alerts:[], members:[], assignments:[], profiles:[], themes:[], curriculum:[], active:null, demo:false, filter:'', onboarding:false, schedules:[], scheduleStudents:[], curriculumTab:'strand', curriculumSubject:'reading', curriculumPhase:'all' });
